#!/usr/bin/env python3
"""Ledger tool for analyzing CSV transaction records."""

import argparse
import csv
import json
import sys
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple

# ANSI color codes
COLORS = {
    "reset": "\033[0m",
    "red": "\033[31m",
    "green": "\033[32m",
    "yellow": "\033[33m",
    "blue": "\033[34m",
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Analyze CSV transaction records."
    )
    parser.add_argument("input_file", help="Path to the CSV file")
    subparsers = parser.add_subparsers(dest="command", required=True)

    # Summary subcommand
    summary_parser = subparsers.add_parser("summary", help="Show totals per category and month")
    summary_parser.set_defaults(func=summary_command)

    # Top subcommand
    top_parser = subparsers.add_parser("top", help="Show largest N expenses")
    top_parser.add_argument("--n", type=int, default=5, help="Number of top entries to show")
    top_parser.set_defaults(func=top_command)

    # Budget subcommand
    budget_parser = subparsers.add_parser("budget", help="Compare against a JSON budget file")
    budget_parser.add_argument("--budget", required=True, help="Path to JSON budget file")
    budget_parser.set_defaults(func=budget_command)

    return parser.parse_args()


def read_transactions(csv_path: str) -> List[Dict[str, str]]:
    """Read CSV file and return list of transaction dicts."""
    transactions = []
    csv_path = Path(csv_path)
    if not csv_path.exists():
        raise FileNotFoundError(f"CSV file not found: {csv_path}")

    with open(csv_path, "r", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row_num, row in enumerate(reader, start=2):
            # Validate required fields
            required_fields = {"date", "payee", "amount", "category"}
            if not required_fields.issubset(row.keys()):
                raise ValueError(
                    f"Row {row_num}: Missing required fields. Expected {required_fields}"
                )
            try:
                date_str = row["date"].strip()
                if not date_str:
                    raise ValueError(f"Row {row_num}: Empty date field")

                # Parse date (YYYY-MM-DD format expected)
                try:
                    _ = datetime.strptime(date_str, "%Y-%m-%d")
                except ValueError:
                    raise ValueError(
                        f"Row {row_num}: Invalid date format '{date_str}', expected YYYY-MM-DD"
                    )

                amount_str = row["amount"].strip()
                try:
                    amount = float(amount_str)
                except ValueError:
                    raise ValueError(
                        f"Row {row_num}: Invalid amount '{amount_str}'"
                    )

                payee = row["payee"].strip()
                if not payee:
                    raise ValueError(f"Row {row_num}: Empty payee field")

                category = row["category"].strip()
                if not category:
                    raise ValueError(f"Row {row_num}: Empty category field")

                transactions.append(
                    {
                        "date": date_str,
                        "payee": payee,
                        "amount": amount,
                        "category": category,
                    }
                )

            except ValueError as e:
                print(f"Warning: {e}", file=sys.stderr)
                continue
    return transactions


def get_month_key(date_str: str) -> str:
    """Convert date string to YYYY-MM format."""
    return date_str[:7]


def summary_command(args: argparse.Namespace) -> None:
    transactions = read_transactions(args.input_file)
    if not transactions:
        print("No valid transactions found.", file=sys.stderr)
        sys.exit(1)

    # Build a dictionary: {month_key: {category: total_amount}}
    totals: Dict[str, Dict[str, float]] = {}
    for t in transactions:
        month = get_month_key(t["date"])
        category = t["category"]
        if month not in totals:
            totals[month] = {}
        totals[month][category] = totals[month].get(category, 0.0) + t["amount"]

    # Sort by month then category
    for month in sorted(totals.keys()):
        categories = sorted(totals[month].items(), key=lambda x: x[0])
        total_month = sum(v for v in totals[month].values())
        print(f"\n{month}")
        for cat, amount in categories:
            sign = "₊" if amount >= 0 else "₋"
            print(f"  {sign} {cat:<15} ${amount:>10.2f}")
        print(f"  Total month: ${total_month:>10.2f}")


def top_command(args: argparse.Namespace) -> None:
    transactions = read_transactions(args.input_file)
    if not transactions:
        print("No valid transactions found.", file=sys.stderr)
        sys.exit(1)

    # Sort by amount descending (largest expenses first)
    sorted_txs = sorted(transactions, key=lambda t: t["amount"], reverse=True)
    top_n = sorted_txs[: args.n]

    # Print header
    print(f"{'Rank':<4} {'Date':<12} {'Payee':<20} {'Category':<15} {'Amount':>10}")
    print("-" * 70)

    for i, t in enumerate(top_n, start=1):
        print(
            f"{i:<4} "
            f"{t['date']:<12} "
            f"{t['payee']:<20} "
            f"{t['category']:<15} "
            f"${t['amount']:>9.2f}"
        )


def load_budget(budget_file: str) -> Dict:
    """Load and validate JSON budget file."""
    budget_file = Path(budget_file)
    if not budget_file.exists():
        raise FileNotFoundError(f"Budget file not found: {budget_file}")

    with open(budget_file, "r", encoding="utf-8") as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in budget file: {e}")

    # Expected structure: {"<category>": {<month>: <limit>, ...}}
    if not isinstance(data, dict):
        raise ValueError("Budget file must be a JSON object.")
    return data


def budget_command(args: argparse.Namespace) -> None:
    transactions = read_transactions(args.input_file)
    if not transactions:
        print("No valid transactions found.", file=sys.stderr)
        sys.exit(1)

    budget = load_budget(args.budget)
    if not budget:
        print("Budget file is empty.", file=sys.stderr)
        sys.exit(1)

    # Compute totals by category and month
    totals: Dict[str, Dict[str, float]] = {}
    for t in transactions:
        month = get_month_key(t["date"])
        category = t["category"]
        key = f"{category}:{month}"
        totals[key] = totals.get(key, 0.0) + t["amount"]

    # Check for overspends
    overspends: List[Tuple[str, str, float, float]] = []
    for key, amount in totals.items():
        parts = key.split(":", 1)
        if len(parts) != 2:
            continue
        category, month = parts
        if category in budget and month in budget[category]:
            limit = budget[category][month]
            if amount > limit:
                overspends.append((category, month, amount, limit))

    # Print summary
    print(f"\nBudget Overview (from '{args.budget}')")
    print(f"{'=' * 60}")

    if not overspends:
        print("\n✅ All within budget!")
    else:
        print("\n⚠️ Overspend alerts:")
        for cat, month, actual, limit in overspends:
            overage = actual - limit
            print(
                f"  [{cat}] {month}: "
                f"Spent ${actual:.2f} / Limit ${limit:.2f} (Over by ${overage:.2f})"
            )


def main() -> int:
    try:
        args = parse_args()
        args.func(args)
        return 0
    except FileNotFoundError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
