import { debounce, DebounceFunction } from './debounce';

// @ts-ignore for fake timers polyfill
jest.useFakeTimers();

describe('debounce utility', () => {
  let mockFn: jest.Mock;

  beforeEach(() => {
    mockFn = jest.fn();
  });

  afterEach(() => {
    jest.clearAllTimers();
  });

  it('should execute once after delay when no leading edge', () => {
    const df = debounce(mockFn, 50, { leading: false, trailing: true });
    df();

    expect(mockFn).not.toHaveBeenCalled();
    jest.advanceTimersByTime(25);
    expect(mockFn).not.toHaveBeenCalled();
    jest.advanceTimersByTime(26);
    expect(mockFn).toHaveBeenCalledTimes(1);
  });

  it('should cancel pending call using cancel()', () => {
    const df = debounce(mockFn, 50);
